    void buildTree(Block base){for(int y=0;y<5;y++)base.getRelative(0,y,0).setType(Material.OAK_LOG,false);for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)if(x!=0||z!=0){Block leaf=base.getRelative(x,4,z);leaf.setType(Material.OAK_LEAVES,false);var data=(org.bukkit.block.data.type.Leaves)leaf.getBlockData();data.setPersistent(false);leaf.setBlockData(data,false);}}
